-- PT104-S4-Q19. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT104-S4-Q19$batch04$ AND q.stimulus=$batch04$Most people feel that they are being confused by the information from broadcast news. This could be the effect of the information’s being delivered too quickly or of its being poorly organized. Analysis of the information content of a typical broadcast news story shows that news stories are far lower in information density than the maximum information density with which most people can cope at any one time. So the information in typical broadcast news stories is poorly organized.$batch04$ AND q.prompt=$batch04$Which one of the following is an assumption that the argument requires in order for its conclusion to be properly drawn?$batch04$ AND q.correct_choice=$batch04$A$batch04$) THEN RAISE EXCEPTION 'Question changed: PT104-S4-Q19'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT104-S4-Q19$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT104-S4-Q19'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT104-S4-Q19$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Conclusion$batch04$, $batch04$The information in typical broadcast news stories is poorly organized.$batch04$), (1, $batch04$Evidence$batch04$, $batch04$People feel confused by broadcast news. This could be because the information comes too fast or because it is poorly organized. News stories are far below the information density most people can handle.$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$The author names two possible causes, rules out one, and concludes the other. That only works if those are the only two. What if something else causes the confusion?$batch04$), (3, $batch04$Goal$batch04$, $batch04$A defender: rule out some other cause of the confusion.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT104-S4-Q19$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Negate it: the *number* of news stories a person sees *is* the source of the confusion. That is a third cause, and poor organization is no longer the only explanation left.$batch04$), ($batch04$B$batch04$, $batch04$The argument does not need poor organization to make understanding *impossible*, only to be the cause of confusion.$batch04$), ($batch04$C$batch04$, $batch04$Whether seeing more stories would help is not about what causes the confusion now.$batch04$), ($batch04$D$batch04$, $batch04$The evidence already says stories are well below what people can handle. The argument does not need people to cope with a *very* high density.$batch04$), ($batch04$E$batch04$, $batch04$Some people being overwhelmed by too much information points toward the "too fast" explanation the author ruled out.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT104-S4-Q19$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
